=<!DOCTYPE html>
<html lang="tr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Flux Resim Oluşturma Sonucu</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Roboto:wght@300;400;500;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --dark-bg: #1a1a1d;
            --card-bg: #2c2c34;
            --text-primary: #f5f5f5;
            --text-secondary: #a9a9b3;
            --accent-primary: #8a42ff;
            --accent-secondary: #4d4d5a;
            --border-color: #40404a;
            --success-color: #28a745;
        }
        body { font-family: 'Roboto', sans-serif; background-color: var(--dark-bg); color: var(--text-primary); display: flex; justify-content: center; align-items: center; min-height: 100vh; padding: 2rem; box-sizing: border-box; }
        .card { display: flex; flex-direction: column; width: 100%; max-width: 960px; background: var(--card-bg); border-radius: 20px; overflow: hidden; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5); border: 1px solid var(--border-color); animation: fadeIn 0.8s ease-out; }
        @keyframes fadeIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .card-content { display: flex; flex-direction: column; }
        .image-pane { flex-basis: 55%; padding: 20px; display: flex; align-items: center; justify-content: center; }
        .image-pane img { max-width: 100%; border-radius: 12px; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3); }
        .details-pane { flex-basis: 45%; padding: 32px; background-color: rgba(0, 0, 0, 0.1); display: flex; flex-direction: column; }
        .details-header h1 { font-size: 2rem; font-weight: 700; margin: 0 0 8px 0; line-height: 1.2; }
        .details-header .subtitle { font-size: 1rem; color: var(--text-secondary); margin-bottom: 24px; }
        .section-title { color: var(--text-secondary); font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px; font-weight: 500; }
        .prompt-area { background: rgba(0,0,0,0.2); border-radius: 8px; padding: 16px; font-size: 0.95rem; line-height: 1.6; margin-bottom: 24px; font-style: italic; color: #dcdce0; }
        .metadata-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 32px; }
        .meta-item { background: var(--accent-secondary); padding: 12px; border-radius: 8px; overflow-wrap: break-word; }
        .meta-item .label { font-size: 0.8rem; color: var(--text-secondary); }
        .meta-item .value { font-size: 1rem; font-weight: 500; color: var(--text-primary); }
        .actions-group { margin-top: auto; display: flex; gap: 12px; }
        .btn { flex-grow: 1; padding: 14px; border-radius: 8px; border: none; font-size: 1rem; font-weight: 500; cursor: pointer; text-decoration: none; text-align: center; transition: all 0.2s ease; }
        .btn-primary { background-color: var(--accent-primary); color: white; }
        .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 4px 10px rgba(138, 66, 255, 0.4); }
        .btn-secondary { background-color: var(--accent-secondary); color: var(--text-primary); }
        .btn-secondary:hover { background-color: #5a5a6a; }
        .copied-feedback { display: none; color: var(--success-color); font-size: 0.9rem; margin-left: 10px; }
        @media (min-width: 800px) { .card-content { flex-direction: row; } }
    </style>
</head>
<body>

<div class="card">
    <div class="card-content">
        <div class="image-pane">
            <img src="{{ $('Resmi Binary Olarak Getir').item.json.data[0].url }}" alt="Oluşturulan Resim">
        </div>
        <div class="details-pane">
            <div class="details-header">
                <h1>Resim Oluşturuldu</h1>
                <p class="subtitle">Flux ile oluşturulan sanat eseriniz.</p>
            </div>

            <p class="section-title">Prompt</p>
            <div class="prompt-area">
                <span id="prompt-text">"{{ $('Image Generator Form').item.json['Prompt to flux'] }}"</span>
            </div>

            <p class="section-title">Detaylar</p>
            <div class="metadata-grid">
                <div class="meta-item">
                    <div class="label">Stil</div>
                    <div class="value">{{ $('Image Generator Form').item.json.Style }}</div>
                </div>
                <div class="meta-item">
                    <div class="label">Inference </div>
                    <div class="value">{{ $('Resim Oluştur(together.ai)').item.json.data[0].timings.inference.round(4) }}   </div>
                </div>
                <div class="meta-item">
                    <div class="label">Model</div>
                    <div class="value">{{ $('Resim Oluştur(together.ai)').item.json.model }}</div>
                </div>
                <div class="meta-item">
                    <div class="label">Gönderim Tarihi</div>
                    <div class="value">{{ new Date($('Image Generator Form').item.json.submittedAt).toLocaleString('tr-TR') }}</div>
                </div>
            </div>

            <div class="actions-group">
                <a href="{{ $('Resmi Binary Olarak Getir').item.json.data[0].url }}" download="flux-image.png" class="btn btn-primary">İndir</a>
                <button class="btn btn-secondary" onclick="copyPrompt()">Prompt'u Kopyala <span id="feedback" class="copied-feedback">✓ Kopyalandı</span></button>
            </div>
        </div>
    </div>
</div>

<script>
    function copyPrompt() {
        const promptText = document.getElementById('prompt-text').innerText;
        const feedbackElement = document.getElementById('feedback');

        navigator.clipboard.writeText(promptText).then(() => {
            feedbackElement.style.display = 'inline';
            setTimeout(() => {
                feedbackElement.style.display = 'none';
            }, 2000);
        }).catch(err => {
            alert('Hata: Prompt kopyalanamadı.');
            console.error('Kopyalama hatası:', err);
        });
    }
</script>

</body>
</html>
